//! Bundle C golden 测试（由 `reference/gen/bundlecvec.c` 的 cubiomes C
//! 参考实现输出生成，`reference/gen/gen_bundlec_tests.py` 转换，请勿手工编辑）。
//!
//! 覆盖结构部件生成：
//! - `getEndCityPieces`：末地城部件树（2 版本 × 4 种子 × 4 真实末地城
//!   区块），逐部件比对 type/rot/depth/pos/bb0/bb1 全部字段；
//! - `getFortressPieces`：下界堡垒布局（≤1.15 的 `setAttemptSeed` 路径与
//!   1.16+ 的 `chunkGenerateRnd` 路径各两代 × 3 种子 × 3 真实堡垒区块）；
//! - `getHouseList`：1.13 及更早村庄房屋列表（3 版本 × 4 种子 × 3 真实
//!   村庄区块），比对 9 类房屋数量与返回的 LCG 状态。
//!
//! 所有输入区块均由 C 程序用 `getStructurePos` + `isViableStructurePos`
//! （末地城另加 `isViableEndCityTerrain`）找到的真实可生成结构。

use minecraft_seed_core::structure::{
    get_end_city_pieces, get_fortress_pieces, get_house_list, Piece,
};
use minecraft_seed_core::McVersion;

fn mc(v: u32) -> McVersion {
    match v {

        15 => McVersion::V1_12,
        18 => McVersion::V1_15,
        20 => McVersion::V1_16,
        22 => McVersion::V1_18,
        _ => panic!("bad mc"),
    }
}

/// 部件记录：`[type, rot, depth, pos.x, pos.y, pos.z, bb0.x, bb0.y, bb0.z,
/// bb1.x, bb1.y, bb1.z]`。
type PieceRec = [i32; 12];

fn piece_rec(p: &Piece) -> PieceRec {
    [
        p.piece_type, p.rot, p.depth,
        p.pos.x, p.pos.y, p.pos.z,
        p.bb0.x, p.bb0.y, p.bb0.z,
        p.bb1.x, p.bb1.y, p.bb1.z,
    ]
}

