#[test]
fn end_city_pieces_match_c() {
    for &(seed, cx, cz, want) in END_CITY_CASES {
        let pieces = get_end_city_pieces(seed as u64, cx, cz);
        assert_eq!(
            pieces.len(),
            want.len(),
            "end city piece count, seed {seed} chunk ({cx}, {cz})"
        );
        for (i, (p, e)) in pieces.iter().zip(want.iter()).enumerate() {
            assert_eq!(
                &piece_rec(p),
                e,
                "end city piece #{i}, seed {seed} chunk ({cx}, {cz})"
            );
        }
    }
}

