#[test]
fn fortress_pieces_match_c() {
    for &(v, seed, cx, cz, want) in FORTRESS_CASES {
        let pieces = get_fortress_pieces(mc(v), seed as u64, cx, cz);
        assert_eq!(
            pieces.len(),
            want.len(),
            "fortress piece count, mc {v} seed {seed} chunk ({cx}, {cz})"
        );
        for (i, (p, e)) in pieces.iter().zip(want.iter()).enumerate() {
            assert_eq!(
                &piece_rec(p),
                e,
                "fortress piece #{i}, mc {v} seed {seed} chunk ({cx}, {cz})"
            );
        }
    }
}

