#[test]
fn house_list_matches_c() {
    for &(seed, cx, cz, want_rng, want_houses) in HOUSE_CASES {
        let got = get_house_list(seed as u64, cx, cz);
        assert_eq!(
            got.houses, want_houses,
            "house counts, seed {seed} chunk ({cx}, {cz})"
        );
        assert_eq!(
            got.rng_state, want_rng,
            "house list rng state, seed {seed} chunk ({cx}, {cz})"
        );
    }
}

